pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Attempt to withdraw with very low gas (2300 gas limit for send)
        vm.prank(address(this));
        (bool success, ) = address(c).call{gas: 2300}(abi.encodeWithSelector(c.withdrawAll.selector, address(0x123)));
        // In reference (transfer): revert => success is false
        // In buggy (send): no revert, returns true but send fails => balance unchanged
        assertTrue(success == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 wei via selfdestruct (no data, no fallback execution)
        address suicider = address(0x1234);
        vm.deal(suicider, 1 wei);
        vm.prank(suicider);
        selfdestruct(payable(address(c)));

        // Now the contract has 1 wei; call withdrawAll with exactly 1 wei of gas.
        // The reference (transfer) will revert on 1 wei gas; the bug (send) will return false silently, leaving balance untouched.
        address recipient = address(0xDEAD);
        vm.deal(address(this), 0);
        vm.prank(address(this));
        vm.startPrank(address(this));
        // Use a gas limit of 1 to force transfer to revert; send will not revert.
        // Note: this works because we are the owner (setUp deploys with owner = address(this)).
        bool success;
        try c.withdrawAll{gas: 1}(recipient) { success = true; } catch { success = false; }
        vm.stopPrank();
        // In the reference, transfer reverts -> catch triggers -> success = false.
        // In the bug, send returns false silently, no revert -> success = true.
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a recipient contract that reverts on receive (no receive/fallback)
        Rejector rejector = new Rejector();
        // Fund the C contract with some ether
        vm.deal(address(c), 1 ether);
        // Owner is address(this), call withdrawAll with the rejector as recipient
        // Reference (transfer): should revert because recipient reverts
        // Buggy (send): should NOT revert (returns false silently)
        bool ok;
        try c.withdrawAll(address(rejector)) {
            ok = true;
        } catch {
            ok = false;
        }
        // The buggy version allows the call to succeed (ok = true) even though no ether was transferred
        // The reference would revert (ok = false). Since we are testing the buggy version,
        // the assertion should be true for the bug and false for the reference.
        // We assert that the call DOES NOT revert (i.e., the bug is triggered)
        // This passes on the mutant and fails on the reference.
        assertTrue(ok);
    }
}

contract Rejector {
    // No receive or fallback, so it rejects Ether transfers
}

