pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract RecipientReverts {
    receive() external payable {
        revert("I don't accept Ether");
    }
}

contract InvMutTest is Test {
    C c;
    RecipientReverts recipient;

    function setUp() public {
        c = new C(address(this));
        recipient = new RecipientReverts();
        vm.deal(address(this), 1 ether);
        payable(address(c)).transfer(1 ether);
    }

    function testRegression_property() public {
        bool ok;
        try c.withdrawAll(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

